def __init__(self, params: LSTMParams, input_size: int, output_size: int) -> None:
    super().__init__()

    self.lstm = nn.LSTM(input_size=input_size, hidden_size=params.hidden_size)

    self.linear = nn.Linear(
        in_features=params.hidden_size, out_features=output_size
    )

def __init__(self, data: TimeSeriesData) -> None:
    super(RobustStatDetector, self).__init__(data=data)
    if not self.data.is_univariate():
        msg = "Only support univariate time series, but get {type}.".format(
            type=type(self.data.value)
        )
        logging.error(msg)
        raise ValueError(msg)
    self.zscore: Optional[npt.NDArray] = None

def __init__(
    self, multi: bool, max_core: Optional[int] = None, **kwargs: Any
) -> None:
    self.multi = multi
    if multi:  # using multi-processing
        total_cores = cpu_count()
        if max_core is None:
            self.max_core: int = max((total_cores - 1) // 2, 1)
        elif isinstance(max_core, int) and max_core > 0 and max_core < total_cores:
            self.max_core = max_core
        elif isinstance(max_core, int) and max_core > total_cores:
            logging.warning(
                f"`max_core` is larger than maximum available cores ({total_cores}) and sets `max_core = {total_cores}`."
            )
        else:
            msg = f"max_core should be a positive integer in [1, {total_cores}] but receives {max_core}."
            logging.error(msg)
            raise ValueError(msg)
    else:
        self.max_core = 1
    self.split_num: int = -1

def __init__(self, alpha: float = 0.1, beta: float = 0.1) -> None:
    self.alpha = alpha
    self.beta = beta
